function real(v: string | undefined): string {
  const s = (v ?? '').trim(); // undefined/whitespace both collapse to ''.
  if (!s) return ''; // blank is unset.
  // Reject leftover .env template text so a placeholder can't flip a capability on.
  if (/^(PASTE|REPLACE|EXAMPLE|CHANGE|YOUR[_-]|<.*>)/i.test(s)) return '';
  return s;
}

export function loadConfig(opts: { envPath?: string } = {}): ToolkitConfig {
  const issues: string[] = []; // collected enable-hints for every off capability.
  const e = process.env;
  const org = real(e.ADO_ORG);
  const project = real(e.ADO_PROJECT);
  const pat = real(e.ADO_PAT);
  // offline is DERIVED, not configured: no PAT => fixture mode.
  const ado: AdoConfig = { org, project, pat, offline: !pat, /* ... */ } as AdoConfig;
  const api: ApiConfig = { baseUrl: real(e.API_BASE_URL), bearerToken: real(e.API_BEARER_TOKEN) } as ApiConfig;
  const db: DbConfig = { connectionString: real(e.DB_CONNECTION_STRING), bridgeDir: real(e.DB_BRIDGE_DIR) };
  const llm: LlmConfig = { googleApiKey: real(e.GOOGLE_API_KEY), anthropicApiKey: real(e.ANTHROPIC_API_KEY) };

  // Each capability is Boolean() over the vars it genuinely needs to function.
  const capabilities = {
    ado: Boolean(org && project),
    api: Boolean(api.baseUrl),
    db: Boolean(db.connectionString || db.bridgeDir), // either backend counts.
    llm: Boolean(llm.googleApiKey || llm.anthropicApiKey),
  };
  // Off capabilities get an actionable hint naming the exact var(s) to set.
  if (!capabilities.db) issues.push('DB capability off: set DB_CONNECTION_STRING or DB_BRIDGE_DIR.');
  return { ado, api, db, llm, capabilities, issues };
}

export function requireCapability(cfg: ToolkitConfig, cap: Capability): void {
  if (cfg.capabilities[cap]) return; // capability present -> proceed silently.
  // Reuse the exact enable-hint loadConfig already produced for this capability.
  const hint = cfg.issues.find(i => i.toLowerCase().startsWith(`${cap} capability`))
    || `${cap} capability is not configured.`;
  // One actionable throw at the point of need, not a mystery failure deep in a call.
  throw new Error(`[qa-agent-toolkit] Required capability "${cap}" is unavailable. ${hint}`);
}

export async function callGemini(prompt: string, opts?: LLMOptions): Promise<LLMResponse> {
  const { googleApiKey } = keysOf(opts); // resolve keys from opts, else env.
  // No primary key -> try the secondary provider (which itself degrades to rules).
  if (!googleApiKey) return callClaudeFallback(prompt, opts);
  // ... call the Gemini API, retrying on 429, falling back on any hard failure
  // Harmless sentinel: empty answer, model 'none' — callers read this as "no AI", not an error.
  return { answer: '', timeMs: 0, model: 'none' };
}

const cfg = loadConfig(); // the exact same seam every agent uses at startup.
// One aligned row per capability: mark + padded label + (off) + reason. Never a secret.
const line = (on: boolean, label: string, note: string) =>
  `  ${on ? '✅' : '⚪'}  ${label.padEnd(22)} ${on ? '' : '(off) '}${note}`;

for (const c of caps) {
  const on = cfg.capabilities[c.key]; // drive the mark straight off the capability map.
  console.log(line(on, c.label, on ? c.on : c.off));
}
// ADO configured (org+project) but PAT-less: call out fixture mode explicitly.
if (cfg.capabilities.ado && cfg.ado.offline) {
  console.log('\n  ℹ️  ADO is in OFFLINE mode (no ADO_PAT): reads/writes use local fixtures.');
}
